package local

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/eukalpia/unio/internal/drive/local/internal/safepath"
)

// layout holds the paths below a drive root. Every name is either a fixed
// name or a hex id generated by the engine. User input never reaches a path.
type layout struct {
	root     string
	format   string
	segments string
	blobs    string
	index    string
	// indexBuild is where a rebuilt index is written before it replaces index,
	// so that no partial index is ever opened as the real one.
	indexBuild string
	tmp        string
}

// newLayout returns the layout of the drive rooted at root. Every path in it is
// built by safepath.Join, from the root and fixed names.
func newLayout(root string) (layout, error) {
	meta, err := safepath.Join(root, ".unio")
	if err != nil {
		return layout{}, err
	}
	lay := layout{root: filepath.Clean(root)}
	for _, f := range []struct {
		dst  *string
		name string
	}{
		{&lay.format, "format.pb"},
		{&lay.segments, "segments"},
		{&lay.blobs, "blobs"},
		{&lay.index, "index"},
		{&lay.indexBuild, "index.rebuild"},
		{&lay.tmp, "tmp"},
	} {
		p, err := safepath.Join(meta, f.name)
		if err != nil {
			return layout{}, err
		}
		*f.dst = p
	}
	return lay, nil
}

// dirs returns the directories that must exist for an opened drive.
func (l layout) dirs() []string {
	return []string{l.segments, l.blobs, l.tmp}
}

// segmentPath returns the file of segment id. The name is 16 hex digits, so the
// path is built only from the drive root and a generated name.
func (l layout) segmentPath(id uint64) (string, error) {
	return safepath.Join(l.segments, segmentName(id))
}

// segmentName returns the file name of segment id: 16 lower-case hex digits.
func segmentName(id uint64) string {
	return fmt.Sprintf("%016x.seg", id)
}

// parseSegmentName is the inverse of segmentName. It reports false for any
// other name.
func parseSegmentName(name string) (uint64, bool) {
	if len(name) != 16+len(".seg") || !strings.HasSuffix(name, ".seg") {
		return 0, false
	}
	id, err := strconv.ParseUint(name[:16], 16, 64)
	if err != nil || segmentName(id) != name {
		return 0, false
	}
	return id, true
}

// listSegments returns the ids of the segment files, ascending.
func (l layout) listSegments() ([]uint64, error) {
	entries, err := os.ReadDir(l.segments)
	if err != nil {
		return nil, fmt.Errorf("local: list segments: %w", err)
	}
	var out []uint64
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if id, ok := parseSegmentName(e.Name()); ok {
			out = append(out, id)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i] < out[j] })
	return out, nil
}
